solution:
def status_counts(lines):
    counts = {}
    for line in lines:
        code = line.split()[-1]
        counts[code] = counts.get(code, 0) + 1
    return counts

alt:
def status_counts(lines):
    counts = {}
    for line in lines:
        code = line.split()[2]
        if code in counts:
            counts[code] += 1
        else:
            counts[code] = 1
    return counts
